const storedLanguage = typeof window === 'undefined' ? null : window.localStorage.getItem(LANGUAGE_STORAGE_KEY);
const initialLanguage = resolveLanguagePreference(storedLanguage);

i18n.on('languageChanged', (language: string) => {
  if (typeof window === 'undefined') return;
  const normalizedLanguage: SupportedLanguage = language === 'en' ? 'en' : 'vi';
  window.localStorage.setItem(LANGUAGE_STORAGE_KEY, normalizedLanguage);
  document.documentElement.lang = normalizedLanguage;
  document.title = i18n.t('app.documentTitle');
});

void i18n.use(initReactI18next).init({
  resources: Object.fromEntries(SUPPORTED_LANGUAGES.map((language) => [language, { translation: translations[language] }])),
  lng: initialLanguage,
  fallbackLng: 'vi',
  interpolation: { escapeValue: false },
});

export default i18n;
